"use client";

import { FormEvent, useEffect, useMemo, useState } from "react";
import {
  Choice, DAILY_ORDERS, DOCTRINES, DoctrineStage, DoctrineVector, FAMILIES, Family, GameState, MANEUVERS,
  Maneuver, Module, Resource, assessment, commit, commitManeuver, coverage, doctrineStage,
  estimateDay, fmt, initialState, liveProjection, maneuverById, maneuverChance, projectForceGeneration, projectOperations, projectProduction, resolve, situationForDay, unlockDoctrine,
} from "./game";
import { CONCEPTS, calculationFor } from "./concepts";
import { OperationsPacket } from "./OperationsPacket";
import { DomesticStatePanel } from "./DomesticStatePanel";
import { DiplomacyPanel } from "./DiplomacyPanel";
import { AdversaryPanel } from "./AdversaryPanel";

const modules: { id: Module; label: string; n: string }[] = [
  { id:"dashboard",label:"Dashboard",n:"00" }, { id:"campaign",label:"Campaign",n:"01" },
  { id:"national",label:"Production",n:"02" }, { id:"military",label:"Military",n:"03" },
  { id:"diplomacy",label:"Diplomacy",n:"04" }, { id:"doctrine",label:"Doctrine",n:"05" },
];
const resourceLabel:Record<Resource,string>={munitions:"Munitions",armor:"Armor",flight:"Flight",drones:"Drones"};
const moduleName=(module:Module)=>module==="national"?"PRODUCTION":module.toUpperCase();
type Metric="population"|"armed"|"enlistment"|"training"|"readiness"|"equipment"|"materiel"|"treasury"|"legitimacy"|"resistance"|"front"|"desertion"|"doctrine";
type Message={who:"AVA"|"YOU";text:string};
type Live=ReturnType<typeof liveProjection>;

const DAY_MS=86_400_000;
const initialClock=()=>{const now=Date.now();const d=new Date(now);d.setHours(0,0,0,0);return{start:d.getTime(),end:d.getTime()+DAY_MS}};
const clockText=(ms:number)=>{const x=Math.max(0,ms);const h=Math.floor(x/3_600_000);const m=Math.floor(x%3_600_000/60_000);const s=Math.floor(x%60_000/1000);const milli=Math.floor(x%1000);return`${String(h).padStart(2,"0")}:${String(m).padStart(2,"0")}:${String(s).padStart(2,"0")}.${String(milli).padStart(3,"0")}`};

const metricInfo=(metric:Metric,s:GameState,live:Live)=>(
  {population:["Population",fmt(s.population,true),`${fmt(s.workforce,true)} workers`,`The living base from which labor, tax, military eligibility, and political tolerance are drawn.`,[`Workforce: ${fmt(s.workforce,true)}`,`Recorded war deaths: ${fmt(18420000-s.population,true)}`]],
  armed:["Armed Forces",fmt(live.armed,true),`${Math.round(live.deployable/Math.max(1,live.armed)*100)}% deployable`,`The force is not waiting for resolution. Combat and desertion continue to spend it while the order remains active.`,[`Authoritative opening force: ${fmt(s.armed,true)}`,`Projected deployable now: ${fmt(live.deployable,true)}`,`Combat losses today: ${fmt(live.losses,true)}`]],
  enlistment:["Enlistment",`${fmt(s.voluntary+s.forced,true)}/day`,"gross intake","People entering the training system. Intake without capacity becomes a political queue, not an army.",[`Voluntary: ${fmt(s.voluntary,true)}`,`Forced: ${fmt(s.forced,true)}`]],
  training:["Training Pipeline",`${fmt(s.queue,true)} queued`,`${fmt(s.training)} capacity/day`,`The conversion layer between recruitment policy and fielded power.`,[`Active cohorts: ${s.trainingCohorts?.length??0}`,`Duration: ${s.duration} days`,`Quality: ${s.quality.toFixed(0)}%`,`Reserves: ${fmt(s.reserves??0,true)}`,`Capacity: ${fmt(s.training,true)}`]],
  readiness:["Soldier Readiness",`${s.readiness.toFixed(0)}%`,s.readiness>65?"combat effective":"degraded","Readiness is attrition without contact. It decays under shortage, excessive tempo, and poor replacements.",[`Training quality: ${s.quality.toFixed(0)}%`,`Operational tempo: ${s.tempo}`]],
  equipment:["Equipment Coverage",`${s.equipment.toFixed(0)}%`,"formations equipped","The share of weapons, vehicles, radios, and support equipment assigned and serviceable.",[`Armor stock: ${fmt(live.production.armor,true)}`,`Flight stock: ${fmt(live.production.flight,true)}`]],
  materiel:["Materiel Condition",`${s.materiel.toFixed(0)}%`,"industrial health","Factory uptime, vehicle serviceability, rail throughput, and maintenance debt.",[`Production target: ${s.target}`,`Lines below 2 days: ${Object.keys(s.production).filter(r=>coverage(s,r as Resource)<2).length}`]],
  treasury:["Treasury",`${s.treasury.toFixed(1)} B`,s.treasury>80?"liquid":"constrained","Immediately spendable fiscal capacity. Recurring policies are charged at resolution.",[`Baseline revenue: 3.4 B/day`,`Army burden: ${(s.armed/185000).toFixed(1)} B/day`]],
  legitimacy:["Legitimacy",`${s.legitimacy.toFixed(0)}%`,s.legitimacy>50?"governable":"brittle","Public willingness to accept losses, taxes, shortages, and the state's account of why they remain necessary.",[`Resistance: ${s.resistance.toFixed(0)}%`,`Atrocity Exposure: ${s.atrocityExposure.toFixed(0)}%`]],
  resistance:["Resistance",`${s.resistance.toFixed(0)}%`,s.resistance<30?"contained":"organized","Draft evasion, sabotage, noncompliance, capital flight, and other friction created by coercive policy.",[`Legitimacy: ${s.legitimacy.toFixed(0)}%`,`Dependency: ${s.dependency.toFixed(0)}%`]],
  front:["Western Front",`${s.front>=0?"+":""}${s.front.toFixed(1)} km`,s.front>=0?"beyond prewar line":"inside prewar line","Reach +12 km to win. Fall to -12 km and the operational system collapses.",[`Enemy strength: ${fmt(s.enemy,true)}`,`Days remaining: ${Math.max(0,30-s.day+1)}`]],
  desertion:["Desertion",fmt(live.deserted,true),`${fmt(live.intercepted,true)} intercepted today`,`Desertion is a continuous personnel flow distinct from casualties. Patrols reduce successful flight by removing forces from the front.`,[`Net flight today: ${fmt(live.netDesertion,true)}`,`Pressure: ${s.desertionPressure.toFixed(0)}%`,`Patrol commitment: ${fmt(s.patrolCommitment,true)}`]],
  doctrine:["Doctrine",`${s.doctrine} insight`,`${s.unlocked.length} principles internalized`,`Doctrine is extracted from novel exposure when observers, telemetry, or surviving officers make the lesson transmissible.`,[`Current situation: ${situationForDay(s.day).sector}`,`Atrocity Exposure: ${s.atrocityExposure.toFixed(0)}%`,`Reciprocity: ${s.reciprocity.toFixed(0)}%`]]}[metric] as [string,string,string,string,string[]]
);

function Dot({tone}:{tone:string}){return<i className={`dot ${tone}`}/>}
function Heading({over,title,note}:{over:string;title:string;note?:string}){return<div className="heading"><div><span className="eyebrow">{over}</span><h2>{title}</h2></div>{note&&<span>{note}</span>}</div>}
function MetricCard({label,value,note,tone="",open}:{label:string;value:string;note:string;tone?:string;open:()=>void}){return<button className="metric" data-semantic="INSPECT" onClick={open}><span><Dot tone={tone}/>{label}</span><b>{value}</b><small>{note}</small><em>Inspect →</em></button>}
function Epigraph({quote,source,skin="paper"}:{quote:string;source:string;skin?:"paper"|"ink"}){return<blockquote className={`epigraph epigraph--${skin}`}><span>“{quote}”</span><cite className="epigraph__source">— {source}</cite></blockquote>}

function DoctrineControlPanel({s,select}:{s:GameState;select:(v:DoctrineVector,stage:DoctrineStage)=>void}){const[first]=DOCTRINES;const[selectedVector,setSelectedVector]=useState(first.id);const[selectedStage,setSelectedStage]=useState(first.stages[0].id);const vector=DOCTRINES.find(v=>v.id===selectedVector)!;const stage=vector.stages.find(x=>x.id===selectedStage)??vector.stages[0];const index=vector.stages.findIndex(x=>x.id===stage.id);const unlocked=s.unlocked.includes(stage.id);const prereq=index===0||s.unlocked.includes(vector.stages[index-1].id);const available=!unlocked&&prereq&&s.doctrine>=stage.cost;return<div className="module doctrine-page" data-module="DOCTRINE"><header><Epigraph quote="A doctrine is born when a battlefield mistake becomes too useful to condemn." source="DOCTRINE ARCHIVE // CANON CORPUS"/><span className="eyebrow">Vectors of war // {s.doctrine} Insight Points available</span><h1>Doctrine</h1><p>Select a vector and principle from the same command hierarchy used throughout the campaign.</p></header><section className="os-window"><div className="os-titlebar"><span>DOCTRINE CONTROL PANEL</span><b>{s.doctrine} INSIGHT POINTS // DAY {s.day}</b></div><div className="os-layout"><nav className="tree-menu doctrine-tree">{DOCTRINES.map(v=><details open key={v.id} className={v.forbidden?"prohibited":""}><summary onClick={()=>{setSelectedVector(v.id);setSelectedStage(v.stages[0].id)}}>{v.forbidden?"! ":"▦ "}{v.label}<small>{v.stages.filter(x=>s.unlocked.includes(x.id)).length}/{v.stages.length}</small></summary>{v.stages.map((x,i)=>{const prior=i===0||s.unlocked.includes(v.stages[i-1].id);const has=s.unlocked.includes(x.id);return<button className={selectedStage===x.id?"selected":""} disabled={!prior} onClick={()=>{setSelectedVector(v.id);setSelectedStage(x.id)}} key={x.id}><span>{has?"☒":prior?"☐":"⊘"}</span>{x.label}<small>{has?"INTERNALIZED":prior?`${x.cost} IP`:"LOCKED"}</small></button>})}</details>)}</nav><article className="menu-inspector doctrine-inspector"><div className="menu-path">DOCTRINE // {vector.label.toUpperCase()} // {stage.label.toUpperCase()}</div><h2>{stage.label}</h2><p>{stage.description}</p><dl><div><dt>VECTOR</dt><dd>{vector.label}</dd></div><div><dt>COST</dt><dd>{stage.cost} IP</dd></div><div><dt>STATUS</dt><dd>{unlocked?"INTERNALIZED":available?"AVAILABLE":prereq?"INSUFFICIENT POINTS":"PREREQUISITE LOCKED"}</dd></div><div><dt>AUTHORITY</dt><dd>{vector.authority}</dd></div></dl><section className="doctrine-effect"><b>DETERMINISTIC EFFECT</b><p>{stage.effect}</p><small>OUTPUT // {stage.output??"Resolution Rule"}</small><small>AFFECTS // {stage.affects??"Eligible formations"}</small></section><button className="os-primary" disabled={!available} onClick={()=>select(vector,stage)}>{unlocked?"ALREADY INTERNALIZED":"REVIEW AND INTERNALIZE →"}</button><div className="win-ledger"><h3>VERIFIED WIN INSIGHT LEDGER</h3>{s.doctrineWinAwards.length?s.doctrineWinAwards.slice(0,4).map(a=><div key={`${a.day}-${a.action}`}><span>DAY {a.day}</span><b>{a.action}</b><small>{a.verified}</small><strong>+{a.reward} IP</strong></div>):<p>NO VERIFIED WINS // MILITARY SUCCESS FUNDS DOCTRINE</p>}</div></article></div><footer className="os-status">SELECT VECTOR → SELECT PRINCIPLE → REVIEW EFFECT → CONFIRM</footer></section></div>}
const GLOSSARY:Record<string,{summary:string;body:string;related:string[]}>= {
  "net-flight":{summary:"Soldiers removed from Active Force by desertion after interceptions.",body:"Net Flight Today equals attempted desertions minus soldiers intercepted by rear-area patrols. It is deducted from Armed Forces and Deployable Force continuously during the day. It is not a casualty and does not reduce Population.",related:["Desertion Pressure","Patrol Commitment","Deployable Force"]},
  "desertion-pressure":{summary:"The daily rate driver for attempted desertion.",body:"Desertion Pressure is a 0–100 index. Casualties, low readiness, forced intake, poor legitimacy, and denied quarter increase it. Family rations, amnesty, and selected personnel policies reduce it. Each point raises the number of attempted desertions generated at resolution.",related:["Net Flight Today","Legitimacy","Readiness"]},
  "patrol-commitment":{summary:"Rear-area personnel assigned to intercept deserters.",body:"Patrol Commitment removes soldiers from useful frontline employment in exchange for intercepting a share of attempted desertions. Establish Desertion Patrols under MILITARY // PERSONNEL SUSTAINMENT // PROCESS DESERTION to increase it.",related:["Process Desertion","Net Flight Today","Resistance"]},
  "doctrine":{summary:"Institutional insight extracted from observed risk and failure.",body:"Doctrine is spent to internalize principles along Doctrine vectors. Risky directives and maneuvers generate insight when observation survives. Doctrine changes deterministic equations and unlocks further stages.",related:["Doctrine Vector","Observation Survival","Risk Class"]},
  "readiness":{summary:"The fraction of a force able to perform its assigned mission now.",body:"Readiness multiplies deployable manpower when combat power is calculated. Tempo, shortages, weak replacements, and losses reduce it. Rest, training quality, and selected policies restore it.",related:["Deployable Force","Equipment Coverage","Operational Tempo"]},
  "resolution":{summary:"The deterministic end-of-day state transition.",body:"Resolution applies scheduled arrivals, active policies, production, recruitment, combat, desertion, Doctrine observation, public reaction, and front movement in a fixed order. Seeded contingent events are resolved here, never by narrative text.",related:["Owned Effects","Contingent Effects","Butcher's Bill"]},
  "pressure":{summary:"A directional modifier to battlefield front movement.",body:"Battlefield Pressure is the combined push or retreat contribution from Operational Tempo, the selected Maneuver, force ratio, intelligence, shortages, and active methods. Positive Pressure tends to move the front forward; negative Pressure tends to concede ground. It is not Desertion Pressure.",related:["Front Movement","Operational Tempo","Force Ratio"]},
  "insight-points":{summary:"Verified battlefield insight spent to internalize Doctrine Techs.",body:"Insight Points are awarded only when a committed military maneuver succeeds. Award = max(10, rounded verified enemy losses ÷ 1,000 × 8 + positive front movement × 20). Failed maneuvers and standing tempo earn zero. Points remain available until spent.",related:["Doctrine","Verified Win","Enemy Losses"]},
  "verified-win":{summary:"A maneuver whose seeded success check resolves successfully.",body:"A Verified Win requires a committed campaign maneuver and a successful deterministic check against its displayed probability. Standing tempo alone cannot earn Insight Points. The result packet records the maneuver, enemy losses, ground movement, and award.",related:["Insight Points","Success Estimate","Campaign Maneuver"]},
  "deployable-force":{summary:"Armed personnel currently available to produce battlefield power.",body:"Deployable Force starts from trained Armed Forces and loses casualties, net desertion, and rear-area commitments. It is multiplied by Readiness and Equipment Coverage to calculate Effective Force.",related:["Readiness","Equipment Coverage","Net Flight Today"]},
  "equipment-coverage":{summary:"Share of field formations with serviceable assigned equipment.",body:"Equipment Coverage multiplies Deployable Force in effective-force calculation. Casualties and shortages reduce it; industrial and external-supply directives can restore it.",related:["Deployable Force","Materiel Condition","Production"]},
  "materiel-condition":{summary:"Industrial uptime, maintenance health, rail throughput, and repair debt.",body:"Materiel Condition modifies production output. High tempo and deferred maintenance reduce it. Maintenance, dispersal, and external support restore it.",related:["Production","Equipment Coverage","Supply"]},
  "operational-tempo":{summary:"Standing rate at which the army exchanges supply and casualties for pressure.",body:"Hold, Methodical, Surge, and Human Wave set casualty, supply-use, and battlefield-pressure multipliers. Tempo remains active until replaced and resolves every day.",related:["Pressure","Casualties","Supply"]},
  "owned-effects":{summary:"Immediate state changes guaranteed when an order is confirmed.",body:"Owned Effects are exact, player-controlled changes applied at commitment or on a declared schedule. They do not depend on enemy response or a probability check.",related:["Contingent Effects","Resolution","Rotation Lock"]},
  "contingent-effects":{summary:"Bounded outcomes not known until deterministic resolution.",body:"Contingent Effects disclose their range or success probability before commitment. Campaign seed and authoritative state resolve them; Ava never chooses the result.",related:["Owned Effects","Success Estimate","Resolution"]},
  "rotation-lock":{summary:"Number of days before an issue family may receive another directive.",body:"Issuing a directive locks its whole issue family for the displayed duration. Inspection remains available while locked; standing policy continues.",related:["Directive","Actions","Standing Policy"]},
  "actions":{summary:"The three shared command orders available each campaign day.",body:"The campaign exposes five command categories. Production directives, Military directives, Diplomacy directives, and campaign maneuvers draw from one three-order budget; Doctrine uses earned Insight Points instead. Orders are freely allocated and unspent orders do not carry forward.",related:["Directive","Campaign Maneuver","Resolution"]},
  "front-movement":{summary:"Daily change in controlled ground on the Western Theater axis.",body:"Front Movement is produced by Pressure, force ratio, intelligence, shortages, Doctrine effects, and the selected maneuver. Reach +12 km to win; fall to −12 km to lose operationally.",related:["Pressure","Effective Force","Victory"]},
  "success-estimate":{summary:"Displayed probability that a selected maneuver produces its winning branch.",body:"The percentage is known before confirmation. A seeded deterministic roll keyed to campaign day, situation, and maneuver selects success or failure at resolution.",related:["Verified Win","Contingent Effects","Insight Points"]},
  "atrocity-exposure":{summary:"Accumulated evidence that prohibited methods were authorized.",body:"Exposure reduces legitimacy and enables diplomatic and reciprocal consequences. It persists beyond the immediate tactical benefit.",related:["Reciprocity","Legitimacy","Prohibited Methods"]},
  "reciprocity":{summary:"Expectation that surrender, custody, and restraint remain mutually available.",body:"Low Reciprocity increases desertion pressure and hardens later violence. Prohibited methods reduce it; selected diplomatic and custody policies may preserve it.",related:["Atrocity Exposure","Desertion Pressure","Legitimacy"]},
  "intelligence":{summary:"Quality of classification used in battlefield conversion and estimates.",body:"Intelligence improves pressure conversion and the reliability of displayed battlefield estimates. It is gained through reconnaissance, statecraft, networks, and Doctrine.",related:["Success Estimate","Pressure","Drone War"]},
  "production":{summary:"Daily conversion of industrial allocation into war stocks.",body:"Each line has allocation, output, use, stock, and days of coverage. Materiel Condition and production focus affect output; tempo and maneuvers affect use.",related:["Materiel Condition","Supply","Coverage"]},
  "legitimacy":{summary:"Public willingness to accept the state's losses, coercion, and account of the war.",body:"Casualties, atrocities, shortages, and coercive policies reduce Legitimacy. Low Legitimacy raises resistance and desertion pressure and can end the campaign.",related:["Resistance","Desertion Pressure","Atrocity Exposure"]},
  "force-reconstitution":{summary:"Doctrine affinity concerned with preserving, rebuilding, and returning formations to usefulness.",body:"Force Reconstitution is the Doctrine category associated with withdrawal, reserve preservation, casualty control, equipment recovery, and rebuilding combat power. A maneuver carrying this label can generate Doctrine evidence for that category when its battlefield result is verified. It is a classification, not an immediate bonus.",related:["Insight Points","Deployable Force","Readiness"]},
  "training-queue":{summary:"Recruits waiting to be admitted into active training cohorts.",body:"The Training Queue receives daily voluntary plus forced intake and loses the number admitted up to Training Capacity. It does not add directly to Armed Forces. Recruits become soldiers only after admission, training duration, and quality-adjusted graduation.",related:["Training Capacity","Training Duration","Armed Forces"]},
  "training-capacity":{summary:"Maximum recruits the induction system can admit into training per day.",body:"Capacity removes recruits from the queue and places them into the conversion pipeline. Capacity above intake reduces backlog. Capacity below intake causes the queue and estimated wait to grow.",related:["Training Queue","Enlistment","Graduates"]},
  "training-duration":{summary:"Nominal number of days required to convert an admitted recruit into a graduate.",body:"Shorter standards produce graduates sooner but generally reduce quality. Daily graduates equal admitted recruits divided by duration, adjusted by training quality.",related:["Training Capacity","Training Quality","Graduates"]},
  "training-quality":{summary:"Quality modifier applied when admitted recruits become usable soldiers.",body:"Training Quality reduces or preserves the share of a cohort that becomes effective graduates. Compressed standards and emergency field training reduce it; academies and full standards improve it.",related:["Training Duration","Graduates","Readiness"]},
  "graduates":{summary:"Quality-adjusted trained personnel added to Armed Forces at resolution.",body:"Graduates are calculated from the admitted cohort divided by Training Duration and multiplied by the quality conversion factor. They replenish Armed Forces and partly replenish Deployable Force.",related:["Training Queue","Training Capacity","Armed Forces"]},
};
function Term({id,children}:{id:keyof typeof GLOSSARY;children:React.ReactNode}){const g=GLOSSARY[id];return<span className="term" tabIndex={0}>{children}<span className="term-tip"><b>{children}</b><span>{g.summary}</span><a href={`?wiki=${id}`} target="_blank" rel="noreferrer">OPEN WIKI ARTICLE ↗</a></span></span>}
function RegistryConcept({id,children}:{id:string;children:React.ReactNode}){const c=CONCEPTS[id];if(!c)return<span>{children}</span>;return<span className="term" data-semantic="CONCEPT" tabIndex={0}>{children}<span className="term-tip"><b>{c.label}</b><span>{c.definition}</span>{c.normal&&<em>NORMAL // {c.normal}</em>}<strong>CONSEQUENCE // {c.consequence}</strong>{c.control&&<button onClick={()=>c.control?.family&&window.dispatchEvent(new CustomEvent("open-family",{detail:c.control.family}))}>CONTROL // {c.control.label} →</button>}<a href={`?wiki=${id}`} target="_blank" rel="noreferrer">OPEN WIKI ARTICLE ↗</a></span></span>}
const conceptSlug=(x:string)=>x.toLowerCase().replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,"");
function WikiConcept({id,label,qualifier}:{id:string;label:string;qualifier?:string}){return<span className="concept-link" tabIndex={0}><span>{qualifier&&<small>{qualifier}</small>}{label}</span><span className="term-tip"><b>{label}</b><span>{GLOSSARY[id]?.summary??`Doctrine classification associated with ${label}. Open its field-manual entry for provenance, effects, and related Techs.`}</span><a href={`?wiki=${id}`} target="_blank" rel="noreferrer">OPEN WIKI ARTICLE ↗</a></span></span>}
function EffectLine({text,s}:{text:string;s:GameState}){const commit=text.match(/Commit ([\d,]+) deployable soldiers/i);const exposure=text.match(/Loss exposure: ([\d,]+) to ([\d,]+)/i);if(commit){const n=Number(commit[1].replaceAll(",",""));return<li className="effect-info" tabIndex={0}>{text}<span className="effect-bubble"><b>FORCE COMMITMENT</b><dl><div><dt>ARMED FORCES NOW</dt><dd>{fmt(s.armed,true)}</dd></div><div><dt>DEPLOYABLE NOW</dt><dd>{fmt(s.deployable,true)}</dd></div><div><dt>PROPOSED COMMITMENT</dt><dd>{fmt(n,true)} // {(n/s.deployable*100).toFixed(1)}%</dd></div><div><dt>UNCOMMITTED DEPLOYABLE</dt><dd>{fmt(s.deployable-n,true)}</dd></div></dl><a href="?wiki=deployable-force" target="_blank" rel="noreferrer">DEPLOYABLE FORCE // WIKI ↗</a></span></li>}if(exposure){const low=Number(exposure[1].replaceAll(",","")),high=Number(exposure[2].replaceAll(",",""));return<li className="effect-info" tabIndex={0}>{text}<span className="effect-bubble"><b>LOSS EXPOSURE // DEPLOYED FORCE</b><dl><div><dt>LOW</dt><dd>{fmt(low,true)} // {(low/s.deployable*100).toFixed(1)}%</dd></div><div><dt>HIGH</dt><dd>{fmt(high,true)} // {(high/s.deployable*100).toFixed(1)}%</dd></div><div><dt>DEPLOYABLE BASIS</dt><dd>{fmt(s.deployable,true)}</dd></div></dl><a href="?wiki=deployable-force" target="_blank" rel="noreferrer">FORCE ACCOUNTING // WIKI ↗</a></span></li>}return<li title="This effect enters the deterministic resolution packet when the order is confirmed.">{text}</li>}
function SuccessEstimate({s,m,compact=false}:{s:GameState;m:Maneuver;compact?:boolean}){const chance=maneuverChance(s,m);const intel=(s.intelligence-42)*.2,ready=(s.readiness-64)*.15,equip=(s.equipment-71)*.15,short=Object.values(s.production).filter(x=>x.stock<x.use*2).length*-3,proof=Math.min(8,(s.affinityProofs[m.vector]??0)*2);return<span className={`success-estimate ${compact?"compact":""}`} tabIndex={0}><b>{Math.round(chance*100)}%</b><small>EXECUTION CONFIDENCE</small><span className="effect-bubble"><b>SUCCESS CALCULATION</b><dl><div><dt>MANEUVER BASE</dt><dd>{Math.round(m.success*100)}%</dd></div><div><dt>INTELLIGENCE</dt><dd>{intel>=0?"+":""}{intel.toFixed(1)}%</dd></div><div><dt>READINESS</dt><dd>{ready>=0?"+":""}{ready.toFixed(1)}%</dd></div><div><dt>EQUIPMENT</dt><dd>{equip>=0?"+":""}{equip.toFixed(1)}%</dd></div><div><dt>SUPPLY SHORTAGES</dt><dd>{short.toFixed(1)}%</dd></div><div><dt>FIELD PROOFS // {s.affinityProofs[m.vector]??0}</dt><dd>+{proof.toFixed(1)}%</dd></div><div><dt>ENEMY ADAPTATION // {s.adversary?.adaptation[m.id]??0}</dt><dd>−{adapt.toFixed(1)}%</dd></div><div><dt>FINAL CLAMPED CHANCE</dt><dd>{Math.round(chance*100)}%</dd></div></dl><code>BASE + INTEL + READINESS + EQUIPMENT − SHORTAGES + FIELD PROOFS − ENEMY ADAPTATION // CLAMP 5–95%</code><a href="?wiki=success-estimate" target="_blank" rel="noreferrer">EXECUTION CONFIDENCE // WIKI ↗</a></span></span>}function ManeuverPayoff({m}:{m:Maneuver}){const magnitude=Math.abs(m.successPressure);const level=magnitude>=2?"DECISIVE":magnitude>=1?"MAJOR":"LIMITED";const direction=m.successPressure>=0?"ADVANCE":"PRESERVATION";return<span className="payoff" tabIndex={0}><b>{level}</b><small>STRATEGIC PAYOFF // {direction}</small><span className="effect-bubble"><b>WHAT SUCCESS BUYS</b><p>On successful execution, this maneuver contributes {m.successPressure>=0?"+":""}{m.successPressure.toFixed(2)} km-equivalent battlefield pressure before force ratio, intelligence, shortages, and other modifiers.</p><p>Execution Confidence asks whether the order works. Strategic Payoff asks how much success matters. They are separate.</p><a href="?wiki=pressure" target="_blank" rel="noreferrer">BATTLEFIELD PRESSURE // WIKI ↗</a></span></span>}
function SignalStream({s,live}:{s:GameState;live:Live}){const[tick,setTick]=useState(0);useEffect(()=>{const id=window.setInterval(()=>setTick(x=>x+1),1800);return()=>window.clearInterval(id)},[]);const feed=[`WESTERN THEATER // ${fmt(live.losses,true)} LOSSES ENTERED IN CURRENT BILL`,`INDUCTION BUREAU // ${fmt(s.queue,true)} PERSONS AWAITING TRAINING DISPOSITION`,`COUNTERBATTERY // UNCLASSIFIED EMITTER MOVED BEYOND GRID REFERENCE`,`18TH FORMATION // EQUIPMENT COVERAGE ${s.equipment.toFixed(0)} PERCENT`,`RAIL AUTHORITY // PRIORITY MUNITIONS CONSIST CLEARED JUNCTION`,`PERSONNEL CONTROL // ${fmt(live.deserted,true)} ABSENCES RECORDED // ${fmt(live.intercepted,true)} INTERCEPTED`,`PATTERN ANALYSIS // ${s.doctrine} INSIGHT POINTS AVAILABLE`,`FIELD WEATHER // LOW CLOUD BASE // ROTARY FLIGHT RESTRICTED`,`SIGNAL COMPANY // RELAY HANDSHAKE RESTORED FOR FORTY-SEVEN SECONDS`,`SUPPLY DIRECTORATE // MUNITIONS COVERAGE ${coverage(s,"munitions").toFixed(1)} DAYS`];const ordered=[...feed.slice(tick%feed.length),...feed.slice(0,tick%feed.length)];return<section className="signals-live"><div className="signals-head"><span>SIGNALS TRAFFIC // CONTINUOUS</span><b>LIVE</b></div><div className="signals-crawl"><div>{[...ordered,...ordered].map((x,i)=><span key={`${tick}-${i}`}><time>{new Date().toLocaleTimeString([], {hour:"2-digit",minute:"2-digit",second:"2-digit"})}</time>{x}</span>)}</div></div><div className="signals-stack">{ordered.slice(0,4).map((x,i)=><button title="Signals traffic is atmospheric reporting generated from current campaign state. It does not create a new game effect." key={x}><time>T+{String(i*18).padStart(3,"0")}</time><span>{x}</span></button>)}</div></section>}

function WarClock({remaining}:{remaining:number}){return<div className="war-clock" data-semantic="STATUS" aria-label="Day resolution clock"><span>DAY RESOLUTION</span><b aria-hidden="true">{clockText(remaining)}</b><small>{remaining<=0?"RESOLUTION DUE":"standing orders remain active"}</small></div>}

function SituationCard({s,open}:{s:GameState;open:()=>void}){
  const situation=situationForDay(s.day);const order=maneuverById(s.maneuver);return<section className={`situation-card ${order?"ordered":""}`} data-overprint={situation.sector.toUpperCase()}>
    <div className="situation-index"><span>DAILY STRATEGIC SITUATION</span><b>{situation.sector}</b><small>{situation.windowHours} HOUR OPPORTUNITY WINDOW</small></div>
    <div className="situation-body"><Epigraph quote={situation.quote} source={situation.attribution} skin="ink"/><h2>{situation.headline}</h2><p>{situation.briefing}</p><div className="conditions"><span>Terrain <b>{situation.terrain}</b></span><span>Ground <b>{situation.ground}</b></span><span>Network <b>{situation.network}</b></span><span>Supply <b>{situation.supply}</b></span><span>Intel <b>{situation.intelligence}</b></span></div></div>
    <div className="situation-order"><span>COMMANDER'S QUESTION</span><h3>{situation.question}</h3>{order?<><small>ORDER ISSUED</small><b>{order.label}</b><p>{order.flavor}</p></>:<><p>No maneuver has been issued. The standing operational tempo will prosecute the day by default.</p><button onClick={open}>Direct the battle →</button></>}</div>
  </section>;
}

function LiveLedger({s,live,inspect}:{s:GameState;live:Live;inspect:(m:Metric)=>void}){
  const estimate=estimateDay(s);return<section><Heading over="Live expenditure" title="The war is moving while you read this" note="Projected from authoritative daily rates"/><div className="live-ledger">
    <button onClick={()=>inspect("armed")}><span>Deployable Force</span><b>{fmt(live.deployable,true)}</b><small>-{fmt(live.losses+live.netDesertion,true)} today</small></button>
    <button onClick={()=>inspect("armed")}><span>Combat Losses</span><b className="red-number">{fmt(live.losses,true)}</b><small>{fmt(estimate.casualty,true)} projected by dusk</small></button>
    <button onClick={()=>window.dispatchEvent(new CustomEvent("open-family",{detail:"desertion"}))}><span>Desertions</span><b>{fmt(live.deserted,true)}</b><small>{fmt(live.intercepted,true)} intercepted</small></button>
    <button onClick={()=>inspect("materiel")}><span>Munitions</span><b>{fmt(live.production.munitions,true)}</b><small>{s.production.munitions.output-s.production.munitions.use<0?"net expenditure":"net accumulation"}</small></button>
    <button onClick={()=>inspect("doctrine")}><span>Doctrine</span><b>{s.doctrine}</b><small>institutional insight</small></button>
  </div></section>;
}

function Dashboard({s,live,inspect,openSituation}:{s:GameState;live:Live;inspect:(m:Metric)=>void;openSituation:()=>void}){
  const latest=s.reports[0];const[balance,tone]=assessment(s);const attr:[[Metric,string,number,string],[Metric,string,number,string],[Metric,string,number,string]]=[["readiness","Soldiers",s.readiness,"Readiness debt accumulating"],["materiel","Materiel",s.materiel,"Maintenance debt accumulating"],["equipment","Equipment",s.equipment,"Coverage of field formations"]];
  return<div className="dash"><div className="dash-main">
    <SituationCard s={s} open={openSituation}/><section className={`morning ${latest.tone}`}><Epigraph quote={latest.epigraph} source={latest.day===1?"COMM. HET CLAXTON, Praetor Corps, Third Division":"COMMAND ETHICS APPENDIX"}/><div><span className="eyebrow">Morning report // Day {latest.day}</span><h1>{latest.title}</h1><p>{latest.body}</p></div></section><LiveLedger s={s} live={live} inspect={inspect}/>
    <section><Heading over="Production capacity" title="What the state can still convert" note="State and continuous projection"/><div className="metrics"><MetricCard label="Population" value={fmt(s.population)} note={`${fmt(s.workforce)} workforce`} open={()=>inspect("population")}/><MetricCard label="Armed Forces" value={fmt(live.armed)} note={`${fmt(live.deployable)} deployable`} tone={s.readiness<50?"bad":"warn"} open={()=>inspect("armed")}/><MetricCard label="Enlistment" value={`${fmt(s.voluntary+s.forced)}/d`} note={`${fmt(s.queue)} awaiting induction`} tone={s.queue>s.training*2?"bad":"warn"} open={()=>inspect("enlistment")}/><MetricCard label="Training" value={`${fmt(s.training)}/d`} note={`${s.duration} days at ${s.quality.toFixed(0)}% quality`} open={()=>inspect("training")}/></div></section>
    <section><Heading over="Industrial throughput" title="Production board" note={`Target: ${s.target}`}/><div className="production"><div className="prod-row head"><span>Line</span><span>Allocation</span><span>Output / Use</span><span>Live Stock</span><span>Coverage</span></div>{(Object.keys(s.production)as Resource[]).map(r=>{const l=s.production[r],days=coverage(s,r);return<button className="prod-row" key={r} onClick={()=>inspect(r==="munitions"?"materiel":"equipment")}><strong><i className={r}/>{resourceLabel[r]}</strong><span>{l.allocation}%</span><span><b>+{fmt(l.output)}</b> / -{fmt(l.use)}</span><span>{fmt(live.production[r])}</span><span className={days<2?"bad-text":days<5?"warn-text":"good-text"}>{days.toFixed(1)} d</span></button>})}</div></section>
    <section><Heading over="Attrition ledger" title="Decay without permission" note="0 is failure // 100 is nominal"/><div className="attrition">{attr.map(([id,label,value,note])=><button key={id} onClick={()=>inspect(id)}><div><span>{label}</span><b>{value.toFixed(0)}%</b></div><i><em style={{width:`${value}%`}}/></i><small>{note}</small></button>)}</div></section>
  </div><aside className="rail">
    <section><span className="eyebrow">Strategic balance</span><h2><Dot tone={tone}/>{balance}</h2><div className="forces"><div><small>Your effective force</small><b>{fmt(live.deployable*s.readiness/100*s.equipment/100)}</b></div><span>vs</span><div><small>Enemy estimate</small><b>{fmt(s.enemy*.52)}</b></div></div><button className="frontline" onClick={()=>inspect("front")}><i style={{left:`${Math.max(2,Math.min(98,(s.front+12)/24*100))}%`}}/></button><div className="ends"><span>-12 defeat</span><b>{s.front>=0?"+":""}{s.front.toFixed(1)} km</b><span>+12 victory</span></div></section>
    <section><span className="eyebrow">Personnel leakage</span><button className="railstat" onClick={()=>window.dispatchEvent(new CustomEvent("open-family",{detail:"desertion"}))}><span>Deserted today</span><b>{fmt(live.deserted,true)}</b></button><button className="railstat" onClick={()=>window.dispatchEvent(new CustomEvent("open-family",{detail:"desertion"}))}><span>Intercepted</span><b>{fmt(live.intercepted,true)}</b></button><button className="railstat" onClick={()=>window.dispatchEvent(new CustomEvent("open-family",{detail:"desertion"}))}><span>Patrol commitment</span><b>{fmt(s.patrolCommitment)}</b></button><button className="railstat" onClick={()=>window.dispatchEvent(new CustomEvent("open-family",{detail:"desertion"}))}><span>Desertion pressure</span><b>{s.desertionPressure.toFixed(0)}%</b></button></section>
    <section><span className="eyebrow">State tolerance</span>{[["Treasury",`${s.treasury.toFixed(1)} B`,"treasury"],["Legitimacy",`${s.legitimacy.toFixed(0)}%`,"legitimacy"],["Resistance",`${s.resistance.toFixed(0)}%`,"resistance"],["Reciprocity",`${s.reciprocity.toFixed(0)}%`,"doctrine"]].map(([a,b,m])=><button className="railstat" key={a} onClick={()=>inspect(m as Metric)}><span>{a}</span><b>{b}</b></button>)}</section>
    <SignalStream s={s} live={live}/>
    <section><span className="eyebrow">Recent decisions</span>{s.decisions.length?s.decisions.slice(0,3).map((x,i)=><div className="arrival" key={i}><span>D{x.day}</span><div><b>{x.choice}</b><small>{x.family}</small></div></div>):<p className="empty">Three orders remain. Inaction is also a daily policy.</p>}</section>
  </aside></div>;
}

function ProductionCircuit({s}:{s:GameState}){const p=projectProduction(s);return<section className="production-circuit"><header><div><small>DAILY CIRCUIT PROJECTION</small><b>{p.target.toUpperCase()}</b></div><div><small>WORKFORCE FACTOR</small><b>{Math.round(p.workforceFactor*100)}%</b></div><div><small>CONDITION FACTOR</small><b>{Math.round(p.conditionFactor*100)}%</b></div><div><small>MAINTENANCE DEBT</small><b>{p.maintenanceDebtAfter.toFixed(0)} / 100</b></div></header><div className="circuit-lines">{p.lines.map(line=><div className={line.status} key={line.resource}><strong>{line.resource.toUpperCase()}</strong><span>{line.allocation}% ALLOCATION</span><b>{line.net>=0?"+":""}{fmt(line.net,true)} NET</b><small>{line.coverage.toFixed(1)} DAYS // {line.status.toUpperCase()}</small></div>)}</div><footer>{s.pendingTarget?`RETOOLING TO ${s.pendingTarget.toUpperCase()} AT RESOLUTION // OUTPUT −28%`:p.shortages?`${p.shortages} CRITICAL BOTTLENECK${p.shortages===1?"":"S"}`:"NO CRITICAL BOTTLENECKS"}</footer></section>}

function ForceGenerationCircuit({s}:{s:GameState}){const f=projectForceGeneration(s);return<section className="force-circuit"><header><div><small>FORCE GENERATION // NEXT RESOLUTION</small><b>{fmt(f.grossIntake,true)} GROSS INTAKE</b></div><div><small>INDUCTION WAIT</small><b>{f.estimatedWaitDays.toFixed(1)} DAYS</b></div><div><small>ACTIVE COHORTS</small><b>{f.cohortsClosing}</b></div><div><small>RESERVE AFTER ASSIGNMENT</small><b>{fmt(f.reservesClosing,true)}</b></div></header><div className="force-pipeline"><div><Term id="training-queue">RECRUITMENT</Term><b>+{fmt(f.grossIntake,true)}</b><small>{fmt(f.voluntaryIntake,true)} voluntary // {fmt(f.forcedIntake,true)} forced</small></div><i>→</i><div><Term id="training-capacity">INDUCTION</Term><b>{fmt(f.admitted,true)}</b><small>{fmt(f.queueClosing,true)} remain queued</small></div><i>→</i><div><RegistryConcept id="training-cohort">COHORTS</RegistryConcept><b>{f.cohortsClosing}</b><small>{f.graduatingCohorts} mature today</small></div><i>→</i><div><RegistryConcept id="graduates">GRADUATES</RegistryConcept><b>{fmt(f.effectiveGraduates,true)}</b><small>{fmt(f.rawGraduates,true)} raw at {s.quality.toFixed(0)}% standard</small></div><i>→</i><div><RegistryConcept id="equipment-assignment">EQUIPMENT</RegistryConcept><b>{fmt(f.equipmentAssigned,true)}</b><small>{fmt(f.reserveAssigned,true)} held for materiel</small></div><i>→</i><div><Term id="deployable-force">FORMATIONS</Term><b>+{fmt(f.deployableAssigned,true)}</b><small>{fmt(f.reserveReleased,true)} recalled from reserve // {fmt(f.deployableClosing,true)} deployable</small></div></div><footer><span>OPENING QUEUE {fmt(f.queueOpening,true)}</span><span>CAPACITY {fmt(f.capacity,true)}/DAY</span><span>ELIGIBLE POOL {fmt(f.eligiblePopulation,true)}</span></footer></section>}

function ModulePage({page,s,select,focus}:{page:Exclude<Module,"dashboard"|"campaign"|"doctrine"|"wiki">;s:GameState;select:(f:Family,c:Choice)=>void;focus?:string}){
  const desc={national:["Production command","Convert society into throughput","Control production, fiscal capacity, public burden, and industrial decisions."],military:["Military command","Feed and govern the force","Recruitment creates pressure. Training converts pressure into soldiers. Operations consume them."],diplomacy:["External command","Trade autonomy for leverage","Move equipment, intelligence, legitimacy, and violence across borders."]}[page];const families=FAMILIES.filter(f=>f.module===page);const[selected,setSelected]=useState(focus??families[0]?.id??"");useEffect(()=>{if(focus&&families.some(f=>f.id===focus))setSelected(focus)},[focus,page]);const selectedFamily=families.find(f=>f.id===selected)??families[0];const groups=[...new Set(families.map(f=>f.category))];const personnel=estimateDay(s);
  return<div className="module desktop-module" data-module={moduleName(page)}><header><span className="eyebrow">{desc[0]}</span><h1>{desc[1]}</h1><p>{desc[2]}</p></header><section className="os-window"><div className="os-titlebar"><span>DIRECTIVE CONTROL PANEL</span><b>{moduleName(page)} // DAY {s.day}</b></div><div className="os-layout"><nav className="tree-menu">{groups.map(group=><details open key={group}><summary>{group}</summary>{families.filter(f=>f.category===group).map(f=>{const locked=Math.max(0,(s.locks[f.id]??0)-s.day);return<button className={selected===f.id?"selected":""} onClick={()=>setSelected(f.id)} key={f.id}><span>▣</span>{f.label}<small>{locked?`LOCKED ${locked}D`:"AVAILABLE"}</small></button>})}</details>)}</nav>{selectedFamily&&<article className="menu-inspector"><div className="menu-path">{moduleName(page)} // {selectedFamily.category.toUpperCase()} // {selectedFamily.label.toUpperCase()}</div><h2>{selectedFamily.label}</h2><p>{selectedFamily.brief}</p>{page==="national"&&selectedFamily.category!=="Home Front"&&<ProductionCircuit s={s}/>}{page==="national"&&selectedFamily.category==="Home Front"&&<DomesticStatePanel s={s}/>}{page==="diplomacy"&&<DiplomacyPanel s={s}/>}{page==="military"&&(selectedFamily.category==="Force Generation"||selectedFamily.category==="Training and Induction")&&<ForceGenerationCircuit s={s}/>}{selectedFamily.id==="desertion"&&<section className="desertion-control"><div><Term id="desertion-pressure">PRESSURE</Term><b>{s.desertionPressure.toFixed(0)} / 100</b><small>Generates attempted flight at resolution</small></div><div><Term id="patrol-commitment">PATROL COMMITMENT</Term><b>{fmt(s.patrolCommitment,true)}</b><small>Removed from frontline employment</small></div><div><Term id="net-flight">PROJECTED NET FLIGHT</Term><b>−{fmt(personnel.netDesertion,true)}</b><small>{fmt(personnel.desertion,true)} attempts − {fmt(personnel.intercepted,true)} intercepted</small></div><div><Term id="deployable-force">DEPLOYABLE AFTER FLIGHT</Term><b>{fmt(Math.max(0,s.deployable-personnel.netDesertion),true)}</b><small>Current {fmt(s.deployable,true)} // before combat losses</small></div></section>}<dl><div><dt>DIRECTIVES</dt><dd>{selectedFamily.choices.length}</dd></div><div><dt>ACTION COST</dt><dd>1</dd></div><div><dt>ROTATION</dt><dd>{selectedFamily.lock} DAYS</dd></div><div><dt>INACTION</dt><dd>STANDING POLICY CONTINUES</dd></div></dl><div className="menu-choice-list expanded">{selectedFamily.choices.map(c=>{const locked=(s.locks[selectedFamily.id]??0)>s.day;return<button key={c.id} disabled={locked||s.actions<1} onClick={()=>select(selectedFamily,c)}><div className="directive-glance"><h3>{c.label}</h3><p>{c.flavor}</p><span>{c.doctrine?"HAZARDOUS // INSIGHT ELIGIBLE ON WIN":"ROUTINE DIRECTIVE"}</span></div><ul>{c.exact.map(x=><li key={x}>{x}</li>)}</ul><div className="directive-risk"><small>CONTINGENT</small><b>{c.risk[0]??"NO CONTINGENT EFFECT"}</b><em>1 ACTION // {selectedFamily.lock}D ROTATION</em></div><strong>REVIEW →</strong></button>})}</div></article>}</div><footer className="os-status">{families.length} ISSUE FAMILIES // {s.actions} ORDERS AVAILABLE</footer></section></div>;
}

function DoctrinePage({s,select}:{s:GameState;select:(v:DoctrineVector,stage:DoctrineStage)=>void}){const[first]=DOCTRINES;const[selectedVector,setSelectedVector]=useState(first.id);const[selectedStage,setSelectedStage]=useState(first.stages[0].id);const vector=DOCTRINES.find(v=>v.id===selectedVector)!;const stage=vector.stages.find(x=>x.id===selectedStage)??vector.stages[0];const index=vector.stages.findIndex(x=>x.id===stage.id);const unlocked=s.unlocked.includes(stage.id);const prereq=index===0||s.unlocked.includes(vector.stages[index-1].id);const available=!unlocked&&prereq&&s.doctrine>=stage.cost;return<div className="module doctrine-page"><header><Epigraph quote="A doctrine is born when a battlefield mistake becomes too useful to condemn." source="DOCTRINE ARCHIVE // CANON CORPUS"/><span className="eyebrow">Vectors of war // {s.doctrine} Insight Points available</span><h1>Doctrine</h1><p>Select a vector, inspect its hierarchy, then open a principle for its exact institutional effects.</p><div className="insight-rule"><Term id="insight-points">INSIGHT POINT AWARD</Term><code>WIN REWARD = MAX(10, ROUND(ENEMY LOSSES ÷ 1,000 × 8 + POSITIVE KM × 20))</code><span>Failed maneuver: 0 points // Standing tempo: 0 points</span></div></header><section className="os-window doctrine-window"><div className="os-titlebar"><span>DOCTRINE MANAGER</span><b>{s.doctrine} INSIGHT POINTS AVAILABLE</b></div><div className="doctrine-os-layout"><nav className="vector-menu">{DOCTRINES.map(v=><button className={`${selectedVector===v.id?"selected":""} ${v.forbidden?"prohibited":""}`} onClick={()=>{setSelectedVector(v.id);setSelectedStage(v.stages[0].id)}} key={v.id}><span>{v.forbidden?"!":"▦"}</span><b>{v.label}</b><small>{v.forbidden?"PROHIBITED METHODS":`${v.stages.filter(x=>s.unlocked.includes(x.id)).length}/${v.stages.length} INTERNALIZED`}</small></button>)}</nav><div className="stage-tree"><div className="menu-path">DOCTRINE // {vector.label.toUpperCase()}</div><h2>{vector.label}</h2>{vector.stages.map((x,i)=>{const has=s.unlocked.includes(x.id);const prior=i===0||s.unlocked.includes(vector.stages[i-1].id);return<button className={`${selectedStage===x.id?"selected":""} ${!prior?"inaccessible":""}`} disabled={!prior} onClick={()=>setSelectedStage(x.id)} key={x.id}><span>{has?"☒":prior?"☐":"⊘"}</span><b>{x.label}</b><small>{has?"INTERNALIZED":prior?`${x.cost} INSIGHT POINTS REQUIRED`:"PREREQUISITE INACCESSIBLE"}</small></button>})}</div><article className="stage-inspector"><span className="eyebrow">PRINCIPLE DETAILS // STAGE {index+1}</span><h2>{stage.label}</h2><p>{stage.description}</p><section><b>DETERMINISTIC EFFECT</b><p>{stage.effect}</p><dl><div><dt>OUTPUT TYPE</dt><dd>{stage.output??"Resolution Rule"}</dd></div><div><dt>AFFECTS</dt><dd>{stage.affects??"Eligible formations"}</dd></div></dl></section><dl><div><dt>COST</dt><dd>{stage.cost} INSIGHT POINTS</dd></div><div><dt>STATUS</dt><dd>{unlocked?"INTERNALIZED":available?"AVAILABLE":prereq?"INSUFFICIENT INSIGHT POINTS":"INACCESSIBLE"}</dd></div></dl><button className="os-primary" disabled={!available} onClick={()=>select(vector,stage)}>{unlocked?"ALREADY INTERNALIZED":"REVIEW AND INTERNALIZE"}</button></article></div><div className="win-ledger"><h3>VERIFIED WIN INSIGHT LEDGER</h3>{s.doctrineWinAwards.length?s.doctrineWinAwards.slice(0,6).map(b=><div key={`${b.day}-${b.action}`}><span>DAY {b.day}</span><b>{b.action}</b><small>{b.verified}</small><strong>+{b.reward} IP</strong></div>):<p>NO VERIFIED WINS // COMMIT A CAMPAIGN MANEUVER AND WIN TO FUND DOCTRINE</p>}</div><footer className="os-status">SELECT VECTOR → SELECT STAGE → REVIEW EFFECT → CONFIRM</footer></section></div>}

function WikiPage({article}:{article:string}){const slug=(x:string)=>x.toLowerCase().replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,"");const dynamic=Object.fromEntries([...FAMILIES.flatMap(f=>[[`issue-${slug(f.label)}`,{summary:f.brief,body:`${f.label} is a ${f.module} issue family containing ${f.choices.length} directives. Issuing one costs 1 Action and locks the family for ${f.lock} days.`,related:f.choices.map(c=>c.label)}],...f.choices.map(c=>[`directive-${slug(c.label)}`,{summary:c.flavor,body:`Owned effects: ${c.exact.join("; ")} Contingent effects: ${c.risk.join("; ")}`,related:[f.label,"Owned Effects","Contingent Effects"]}])]),...MANEUVERS.map(m=>[`maneuver-${slug(m.label)}`,{summary:m.flavor,body:`Success estimate ${Math.round(m.success*100)}%. Exact commitment: ${m.exact.join("; ")} Contingent result: ${m.risk.join("; ")}`,related:[m.vector,"Success Estimate","Insight Points"]}]),...DOCTRINES.flatMap(v=>[[`vector-${slug(v.label)}`,{summary:`Doctrine vector administered by ${v.authority}.`,body:`Contains ${v.stages.length} sequential Doctrine Techs. ${v.forbidden?"Classified as Prohibited Methods.":"Purchased with verified-win Insight Points."}`,related:v.stages.map(s=>s.label)}],...v.stages.map(s=>[`doctrine-${slug(s.label)}`,{summary:s.description,body:`Output: ${s.output??"Resolution Rule"}. Affects: ${s.affects??"eligible formations"}. Cost: ${s.cost} Insight Points. Effect: ${s.effect}`,related:[v.label,"Insight Points"]}])]),...Object.values(situationForDay?[]:[]) ] as [string,{summary:string;body:string;related:string[]}][]);const registered=Object.fromEntries(Object.entries(CONCEPTS).map(([id,c])=>[id,{summary:c.definition,body:`${c.consequence}${c.normal?` Normal: ${c.normal}.`:""}${c.control?` Controlled by ${c.control.module.toUpperCase()} // ${c.control.label}.`:""}`,related:c.related}]));const all={...GLOSSARY,...registered,...dynamic};const ids=Object.keys(all);const[active,setActive]=useState(all[article]?article:ids[0]);const[query,setQuery]=useState("");const visible=ids.filter(id=>id.includes(query.toLowerCase().replaceAll(" ","-")));const g=all[active];return<div className="wiki"><header><span className="eyebrow">DELENDA.QUEST FIELD MANUAL</span><h1>Campaign Wiki</h1><p>Authoritative definitions for the deterministic substrate. If a number changes the war, its rule belongs here.</p></header><div className="wiki-layout"><aside><input aria-label="Search wiki" value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search the field manual"/><h3>CONTENTS</h3>{visible.map(id=><button className={active===id?"active":""} onClick={()=>setActive(id)} key={id}>{id.replaceAll("-"," ")}</button>)}</aside><article id={`wiki-${active}`}><div className="wiki-breadcrumb">FIELD MANUAL &gt; SIMULATION CONCEPTS &gt; {active.replaceAll("-"," ").toUpperCase()}</div><h1>{active.replaceAll("-"," ")}</h1><p className="wiki-lead">{g.summary}</p><div className="wiki-rule"><b>DEFINITION</b><p>{g.body}</p></div><h2>Related concepts</h2><ul>{g.related.map(x=>{const id=x.toLowerCase().replaceAll(" ","-");return<li key={x}>{all[id]?<button onClick={()=>setActive(id)}>{x}</button>:<span>{x}</span>}</li>})}</ul><footer>LAST VERIFIED // DETERMINISTIC RULESET V0.2</footer></article></div></div>}

function Overlay({children,close,kind=""}:{children:React.ReactNode;close:()=>void;kind?:string}){return<div className={`overlay ${kind}`} onMouseDown={e=>e.target===e.currentTarget&&close()}>{children}</div>}
function Close({onClick}:{onClick:()=>void}){return<button className="close" aria-label="Close" onClick={onClick}>×</button>}
function Actions({cancel,action,label,danger=false,disabled=false}:{cancel:()=>void;action:()=>void;label:string;danger?:boolean;disabled?:boolean}){return<div className="actions"><button onClick={cancel}>Cancel</button><button disabled={disabled} className={danger?"danger":"primary"} onClick={action}>{label}</button></div>}

function CampaignPage({s,selected,setSelected,review}:{s:GameState;selected:Maneuver|null;setSelected:(m:Maneuver)=>void;review:()=>void}){const situation=situationForDay(s.day);const options=situation.maneuvers.map(id=>MANEUVERS.find(m=>m.id===id)!).filter(Boolean);const current=selected??options[0];useEffect(()=>{if(!selected&&options[0])setSelected(options[0])},[]);return<div className="module campaign-page" data-module="CAMPAIGN"><header><span className="eyebrow">Western theater // Daily operational decision</span><h1>Campaign</h1><p>{situation.briefing}</p></header><section className="os-window campaign-workspace"><div className="os-titlebar"><span>CAMPAIGN MANEUVER CONTROL</span><b>{situation.sector.toUpperCase()} // DAY {s.day}</b></div><div className="campaign-menu-layout"><nav className="maneuver-list"><header>AUTHORIZED MANEUVERS</header>{options.map(m=><button className={current?.id===m.id?"selected":""} key={m.id} onClick={()=>setSelected(m)}><span>▣</span><div className="maneuver-title"><h3>{m.label}</h3></div><div className="row-confidence"><SuccessEstimate s={s} m={m} compact/></div></button>)}</nav>{current&&<article className="maneuver-detail"><div className="menu-path">CAMPAIGN // MANEUVER</div><h2>{current.label}</h2><WikiConcept id={GLOSSARY[conceptSlug(current.vector)]?conceptSlug(current.vector):`vector-${conceptSlug(current.vector)}`} label={current.vector} qualifier="DOCTRINE LEARNING PATH"/><p className="affinity-explainer">A verified win adds one Field Proof to this learning path. Each proof improves related maneuver confidence. Doctrine Techs add new options and better-odds variants.</p><p>{current.flavor}</p><div className="outcome-separation"><SuccessEstimate s={s} m={current}/><ManeuverPayoff m={current}/></div><AdversaryPanel s={s} m={current}/><OperationsPacket s={s} m={current}/><div className="maneuver-contract"><section><h3>Owned effects // exact</h3><ul>{current.exact.map(x=><EffectLine text={x} s={s} key={x}/>)}</ul></section><section><h3>War effects // contingent</h3><ul>{current.risk.map(x=><EffectLine text={x} s={s} key={x}/>)}</ul></section></div><button className="os-primary campaign-review" onClick={review}>REVIEW AND ISSUE ORDER →</button></article>}</div><footer className="os-status">SELECT MANEUVER // INSPECT CONFIDENCE AND PAYOFF // REVIEW ORDER</footer></section></div>}

function SituationModal({s,pending,setPending,confirm,close}:{s:GameState;pending:Maneuver|null;setPending:(m:Maneuver|null)=>void;confirm:()=>void;close:()=>void}){const situation=situationForDay(s.day);const options=situation.maneuvers.map(id=>MANEUVERS.find(m=>m.id===id)!).filter(Boolean);const[view,setView]=useState<"campaign"|"maneuver">("maneuver");const selected=pending??options[0];useEffect(()=>{if(!pending&&options[0])setPending(options[0])},[]);return<Overlay close={close} kind="center"><div className="battle-modal os-window campaign-menu"><div className="os-titlebar"><span>CAMPAIGN DECISION</span><b>{situation.sector.toUpperCase()} // DAY {s.day}</b></div><Close onClick={close}/><nav className="decision-breadcrumb"><button className={view==="campaign"?"active":""} onClick={()=>setView("campaign")}>CAMPAIGN</button><span>›</span><button className={view==="maneuver"?"active":""} onClick={()=>setView("maneuver")}>MANEUVER</button></nav>{view==="campaign"?<article className="campaign-overview"><div className="menu-path">CAMPAIGN // {situation.sector.toUpperCase()}</div><h2>{situation.headline}</h2><p>{situation.briefing}</p><div className="campaign-facts">{[["TERRAIN",situation.terrain],["GROUND",situation.ground],["NETWORK",situation.network],["SUPPLY",situation.supply],["INTELLIGENCE",situation.intelligence]].map(([a,b])=><button title={`${a} constrains today's maneuver outcomes.`} onClick={()=>setView("maneuver")} key={a}><small>{a}</small><b>{b}</b></button>)}</div><button className="os-primary" onClick={()=>setView("maneuver")}>REVIEW MANEUVERS →</button></article>:<div className="campaign-menu-layout"><nav className="maneuver-list"><header>AUTHORIZED MANEUVERS</header>{options.map(m=><button className={selected?.id===m.id?"selected":""} key={m.id} onClick={()=>setPending(m)}><span>▣</span><div className="maneuver-title"><h3>{m.label}</h3></div><div className="row-confidence"><SuccessEstimate s={s} m={m} compact/></div></button>)}</nav>{selected&&<article className="maneuver-detail"><div className="menu-path">CAMPAIGN // MANEUVER</div><h2>{selected.label}</h2><WikiConcept id={GLOSSARY[conceptSlug(selected.vector)]?conceptSlug(selected.vector):`vector-${conceptSlug(selected.vector)}`} label={selected.vector} qualifier="DOCTRINE LEARNING PATH"/><p className="affinity-explainer">A verified win adds one Field Proof to this path. Each proof adds +2% Execution Confidence, up to +8%. Doctrine Techs in the path add new maneuver options and better-odds variants.</p><p>{selected.flavor}</p><div className="outcome-separation"><SuccessEstimate s={s} m={selected}/><ManeuverPayoff m={selected}/></div><AdversaryPanel s={s} m={selected}/><OperationsPacket s={s} m={selected}/><div className="maneuver-contract"><section><h3>Owned effects // exact</h3><ul>{selected.exact.map(x=><EffectLine text={x} s={s} key={x}/>)}</ul></section><section><h3>War effects // contingent</h3><ul>{selected.risk.map(x=><EffectLine text={x} s={s} key={x}/>)}</ul></section></div><div className="insight-on-win"><Term id="insight-points">INSIGHT AWARD ON VERIFIED WIN</Term><b>CALCULATED FROM VERIFIED ENEMY LOSSES + POSITIVE GROUND GAIN</b><small>No fixed range. Failure awards 0. Current {selected.vector} Field Proofs: {s.affinityProofs[selected.vector]??0}.</small></div></article>}</div>}<footer className="campaign-actions"><span>{s.maneuver?"AN OPERATIONAL ORDER ALREADY EXISTS":"ONE MANEUVER SELECTED // REVIEW CONFIDENCE AND PAYOFF SEPARATELY"}</span><Actions cancel={close} action={confirm} label="Issue operational order" disabled={!selected||!!s.maneuver||s.actions<1}/></footer></div></Overlay>}

function DoctrineConfirm({vector,stage,s,yes,no}:{vector:DoctrineVector;stage:DoctrineStage;s:GameState;yes:()=>void;no:()=>void}){return<Overlay close={no} kind="center"><div className={`modal doctrine-confirm ${vector.forbidden?"atrocity-confirm":""}`}><Close onClick={no}/><span className="eyebrow">{vector.forbidden?"Institutional atrocity":"Internalize doctrine"} // {vector.label}</span><h2>{stage.label}</h2><blockquote>“{vector.quote}”</blockquote><div className="effects"><section><h3>Institutional change // exact</h3><p>{stage.description}</p><b>{stage.effect}</b></section><section><h3>{vector.forbidden?"Irreversible exposure":"Acquisition cost"}</h3><p>{stage.cost} Doctrine insight will be consumed.</p><b>{s.doctrine-stage.cost} insight remains</b></section></div><Actions cancel={no} action={yes} label={vector.forbidden?"Authorize prohibited method":"Internalize doctrine"} danger={vector.forbidden}/></div></Overlay>}

function FamilyDrawer({family,s,choose,close}:{family:Family;s:GameState;choose:(c:Choice)=>void;close:()=>void}){const locked=Math.max(0,(s.locks[family.id]??0)-s.day);return<Overlay close={close}><aside className="drawer"><Close onClick={close}/><span className="eyebrow">{family.category} // {family.module}</span><h2>{family.label}</h2><p>{family.brief}</p><div className="contract"><span>{s.actions} actions available</span><span>{family.lock} day rotation lock</span><span>1 action to issue</span></div>{locked>0&&<div className="locked">This family reopens in {locked} day{locked===1?"":"s"}. Inspection remains available.</div>}<div className="choices">{family.choices.map(c=><button key={c.id} disabled={locked>0||s.actions<1||s.status!=="active"} className={s.active[family.id]===c.id?"active":""} onClick={()=>choose(c)}><h3>{c.label}{s.active[family.id]===c.id&&<span>ACTIVE</span>}</h3><p>{c.flavor}</p><ul>{c.exact.slice(0,4).map(x=><li key={x}>{x}</li>)}</ul>{c.doctrine&&<b className="doctrine-yield">DOCTRINE-ELIGIBLE RISK // INSIGHT ONLY ON VERIFIED WIN</b>}<em>Review directive →</em></button>)}</div></aside></Overlay>}
function Confirm({family,choice,s,yes,no}:{family:Family;choice:Choice;s:GameState;yes:()=>void;no:()=>void}){return<Overlay close={no} kind="center"><div className="modal"><Close onClick={no}/><Epigraph quote={choice.flavor} source={`FORM 27-B // ${family.category.toUpperCase()}`}/><span className="eyebrow">CONFIRM DIRECTIVE // {family.category} // {family.module}</span><h2>{choice.label}</h2><div className="effects"><section><h3>Owned effects // exact</h3><ul>{choice.exact.map(x=><li key={x}>{x}</li>)}</ul></section><section><h3>War effects // contingent</h3><ul>{choice.risk.map(x=><li key={x}>{x}</li>)}</ul></section></div><section className="state-calculus"><h3>STATE TRANSITION CALCULUS</h3>{Object.entries(choice.delta??{}).map(([key,change])=>{const before=s[key as keyof GameState];return typeof before==="number"?<div key={key}><span>{key.toUpperCase()}</span><b>{before.toLocaleString()}</b><i>{Number(change)>=0?"+":""}{Number(change).toLocaleString()}</i><strong>{(before+Number(change)).toLocaleString()}</strong></div>:null})}{choice.target&&<div><span>PRODUCTION TARGET</span><b>{s.target.toUpperCase()}</b><i>→</i><strong>{choice.target.toUpperCase()}</strong></div>}{choice.tempo&&<div><span>OPERATIONAL TEMPO</span><b>{s.tempo.toUpperCase()}</b><i>→</i><strong>{choice.tempo.toUpperCase()}</strong></div>}</section><div className="confirmline"><span>Cost</span><b>1 of {s.actions} remaining actions</b><span>Rotation</span><b>{family.lock} days</b></div><p className="opportunity">This consumes 1 of {DAILY_ORDERS}. Unspent orders do not carry to tomorrow.</p><Actions cancel={no} action={yes} label="Issue directive"/></div></Overlay>}
function MetricDrawer({metric,s,live,close}:{metric:Metric;s:GameState;live:Live;close:()=>void}){const[label,value,status,body,factors]=metricInfo(metric,s,live);const calc=calculationFor(metric,s);return<Overlay close={close}><aside className="drawer metric-drawer"><Close onClick={close}/><span className="eyebrow">Deterministic state inspection</span><h2>{label}</h2><strong className="bigvalue">{value}</strong><em className="status">{status}</em><p>{body}</p>{metric==="training"&&(()=>{const intake=s.voluntary+s.forced;const admitted=Math.min(s.queue,s.training);const graduates=Math.round(admitted/s.duration*Math.max(.35,(s.quality-20)/80));const wait=s.queue/Math.max(1,s.training);const nextQueue=Math.max(0,s.queue+intake-admitted);return<section className="training-ledger"><div className="pipeline-verdict"><b>{wait<1?"NORMAL":wait<2?"ELEVATED":"CONGESTED"}</b><span>{wait.toFixed(2)} CAPACITY-DAYS OF BACKLOG // NORMAL BAND 0.50–1.50</span></div><div className="pipeline-flow"><div><Term id="training-queue">QUEUE NOW</Term><strong>{fmt(s.queue,true)}</strong><small>Inherited opening backlog plus unresolved intake. It is waiting, not training.</small></div><i>+</i><div><Term id="training-capacity">DAILY INTAKE</Term><strong>{fmt(intake,true)}</strong><small>{fmt(s.voluntary,true)} voluntary + {fmt(s.forced,true)} forced</small></div><i>−</i><div><Term id="training-capacity">ADMITTED TODAY</Term><strong>{fmt(admitted,true)}</strong><small>Minimum of queue and {fmt(s.training,true)} daily capacity</small></div><i>=</i><div><Term id="training-queue">QUEUE AT RESOLUTION</Term><strong>{fmt(nextQueue,true)}</strong><small>{nextQueue<s.queue?"Backlog contracts":"Backlog grows"}</small></div></div><div className="training-output"><button><Term id="training-duration">TRAINING DURATION</Term><b>{s.duration} DAYS</b><small>Nominal conversion time after admission</small></button><button><Term id="training-quality">TRAINING QUALITY</Term><b>{s.quality.toFixed(0)}%</b><small>Quality-adjusted graduation conversion</small></button><button><Term id="graduates">PROJECTED GRADUATES</Term><b>{fmt(graduates,true)}</b><small>Added to Armed Forces at resolution</small></button><button><Term id="training-queue">QUEUE PROVENANCE</Term><b>CAMPAIGN OPENING STATE</b><small>The initial 76,000 did not accumulate during played days; it is inherited war-state debt.</small></button></div><button className="pipeline-control" onClick={()=>window.dispatchEvent(new CustomEvent("open-family",{detail:"training-capacity"}))}>OPEN PROVISION TRAINING CAPACITY CONTROLS →</button></section>})()}{metric==="desertion"&&<section className="definition-grid"><div><Term id="net-flight">NET FLIGHT TODAY</Term><b>{fmt(live.netDesertion,true)}</b></div><div><Term id="desertion-pressure">DESERTION PRESSURE</Term><b>{s.desertionPressure.toFixed(0)} / 100</b></div><div><Term id="patrol-commitment">PATROL COMMITMENT</Term><b>{fmt(s.patrolCommitment,true)}</b></div><button onClick={()=>window.dispatchEvent(new CustomEvent("open-family",{detail:"desertion"}))}>OPEN PROCESS DESERTION CONTROLS →</button></section>}<section className="factors"><h3>Current factors</h3>{factors.map(x=><div key={x}>{x}</div>)}</section><section className="formula metric-calculation" data-semantic="INSPECT"><span>{calc.title}</span><code>{calc.equation}</code><small>{calc.basis}</small><div>{calc.rows.map(row=><button className={row.tone??"neutral"} key={row.label}>{row.concept?<RegistryConcept id={row.concept}>{row.label}</RegistryConcept>:row.label}<b>{row.value}</b></button>)}</div><strong>{calc.result}</strong>{calc.uncertainties?.map(x=><p className="audit-gap" key={x}>{x}</p>)}</section></aside></Overlay>}

export default function Home(){
  const[s,setS]=useState<GameState>(initialState);const[page,setPage]=useState<Module>("dashboard");const[focusFamily,setFocusFamily]=useState<string|undefined>();const[family,setFamily]=useState<Family|null>(null);const[pending,setPending]=useState<Choice|null>(null);const[metric,setMetric]=useState<Metric|null>(null);const[dayModal,setDayModal]=useState(false);const[reset,setReset]=useState(false);const[ava,setAva]=useState(false);const[input,setInput]=useState("");const[situationOpen,setSituationOpen]=useState(false);const[pendingManeuver,setPendingManeuver]=useState<Maneuver|null>(null);const[pendingDoctrine,setPendingDoctrine]=useState<{vector:DoctrineVector;stage:DoctrineStage}|null>(null);const[clock,setClock]=useState(initialClock);const[now,setNow]=useState(()=>Date.now());const[ledgerNow,setLedgerNow]=useState(()=>Date.now());const[ordersStamped,setOrdersStamped]=useState(false);const[dispatch,setDispatch]=useState<{open:boolean;day:number}|null>(null);
  const[messages,setMessages]=useState<Message[]>([{who:"AVA",text:"The Kesh corridor remains open. At the present rate, 4,218 additional soldiers will be gone by dusk. The reserve has not been directed."}]);const[wikiArticle,setWikiArticle]=useState("resolution");
  useEffect(()=>{const requested=new URLSearchParams(window.location.search).get("wiki");if(requested&&GLOSSARY[requested]){setWikiArticle(requested);setPage("wiki")}},[]);
  useEffect(()=>{const reduced=window.matchMedia("(prefers-reduced-motion: reduce)").matches;const clockId=window.setInterval(()=>setNow(Date.now()),reduced?1000:47);const ledgerId=window.setInterval(()=>setLedgerNow(Date.now()),1700);return()=>{window.clearInterval(clockId);window.clearInterval(ledgerId)}},[]);
  useEffect(()=>{const closeTop=(e:KeyboardEvent)=>{if(e.key!=="Escape")return;if(pendingDoctrine)setPendingDoctrine(null);else if(pending)setPending(null);else if(family)setFamily(null);else if(metric)setMetric(null);else if(situationOpen){setSituationOpen(false);setPendingManeuver(null)}else if(dayModal)setDayModal(false);else if(reset)setReset(false);else if(ava)setAva(false)};window.addEventListener("keydown",closeTop);return()=>window.removeEventListener("keydown",closeTop)},[pendingDoctrine,pending,family,metric,situationOpen,dayModal,reset,ava]);
  useEffect(()=>{const wiki=(e:Event)=>{setWikiArticle((e as CustomEvent<string>).detail);setPage("wiki")};const familyEvent=(e:Event)=>{const hit=FAMILIES.find(f=>f.id===(e as CustomEvent<string>).detail);if(hit){setMetric(null);setFocusFamily(hit.id);setPage(hit.module)}};window.addEventListener("open-wiki",wiki);window.addEventListener("open-family",familyEvent);return()=>{window.removeEventListener("open-wiki",wiki);window.removeEventListener("open-family",familyEvent)}},[]);
  const fraction=Math.max(0,Math.min(1,(ledgerNow-clock.start)/(clock.end-clock.start)));const live=useMemo(()=>liveProjection(s,fraction),[s,fraction]);const[balance,tone]=useMemo(()=>assessment(s),[s]);const remaining=clock.end-now;
  const recordCompletion=(next:GameState)=>{if(next.actions===0){setOrdersStamped(true);window.setTimeout(()=>setOrdersStamped(false),2400)}};
  const issue=()=>{if(!family||!pending)return;const next=commit(s,family,pending);setS(next);recordCompletion(next);setMessages(m=>[...m,{who:"AVA",text:`${pending.label} issued. ${next.actions} actions remain. Owned effects have entered the state graph.`}]);setPending(null);setFamily(null)};
  const issueManeuver=()=>{if(!pendingManeuver)return;const next=commitManeuver(s,pendingManeuver);setS(next);recordCompletion(next);setMessages(m=>[...m,{who:"AVA",text:`${pendingManeuver.label} is now prosecuting ${situationForDay(s.day).sector}. Estimated success is ${Math.round(pendingManeuver.success*100)}%. I will preserve the observation if anything survives to report it.`}]);setSituationOpen(false);setPendingManeuver(null)};
  const internalize=()=>{if(!pendingDoctrine)return;const next=unlockDoctrine(s,pendingDoctrine.stage.id);setS(next);setMessages(m=>[...m,{who:"AVA",text:`${pendingDoctrine.stage.label} has been internalized. Doctrine is now ${next.doctrine}. ${pendingDoctrine.stage.effect}`}]);setPendingDoctrine(null)};
  const advance=()=>{const next=resolve(s);setS(next);setDayModal(false);setDispatch({open:false,day:s.day});const n=Date.now();setClock({start:n,end:n+DAY_MS});setNow(n);setLedgerNow(n);setMessages(m=>[...m,{who:"AVA",text:`Day ${next.day} is open. ${next.reports[0].body}`}])};
  const run=(e:FormEvent)=>{e.preventDefault();const raw=input.trim();if(!raw)return;const q=raw.toLowerCase();setMessages(m=>[...m,{who:"YOU",text:raw}]);setInput("");let answer="Command not recognized. Type help for the command surface.";
    if(q==="help")answer="Commands: status, situation, forecast, open <module>, inspect desertion, inspect doctrine, maneuver <name>, choose <directive>, resolve day.";
    else if(q==="status")answer=`Day ${s.day}. ${s.actions} actions remain. ${balance}. ${fmt(live.losses,true)} combat losses and ${fmt(live.deserted,true)} desertions have accrued today.`;
    else if(q==="situation"){setSituationOpen(true);answer=`${situationForDay(s.day).headline}. Operational direction opened.`}
    else if(q==="forecast")answer=`By resolution: ${fmt(estimateDay(s).casualty,true)} combat losses, ${fmt(estimateDay(s).desertion,true)} desertions, and ${coverage(s,"munitions").toFixed(1)} days of Munitions coverage. Current order: ${maneuverById(s.maneuver)?.label??"standing tempo only"}.`;
    else if(q.startsWith("open ")){const x=q.slice(5)as Module;if(modules.some(m=>m.id===x)){setPage(x);answer=`${x} module opened.`}}
    else if(q.startsWith("inspect ")){const map:Record<string,Metric>={population:"population",army:"armed",forces:"armed",training:"training",readiness:"readiness",equipment:"equipment",materiel:"materiel",treasury:"treasury",legitimacy:"legitimacy",resistance:"resistance",front:"front",desertion:"desertion",doctrine:"doctrine"};const x=map[q.slice(8)];if(x==="desertion"){setFocusFamily("desertion");setPage("military");answer="Military // Personnel Sustainment // Process Desertion opened."}else if(x){setMetric(x);answer=`${metricInfo(x,s,live)[0]} opened for inspection.`}}
    else if(q.startsWith("maneuver ")){const x=q.slice(9);const hit=MANEUVERS.find(m=>m.label.toLowerCase().includes(x)||m.id===x);if(hit){setPendingManeuver(hit);setSituationOpen(true);answer=`${hit.label} staged. Exact and contingent effects await confirmation.`}}
    else if(q.startsWith("choose ")){const x=q.slice(7);const hit=FAMILIES.flatMap(f=>f.choices.map(c=>({f,c}))).find(z=>z.c.label.toLowerCase().includes(x)||z.c.id.includes(x.replaceAll(" ","-")));if(hit){setFamily(hit.f);setPending(hit.c);answer=`${hit.c.label} staged for confirmation.`}}
    else if(q==="resolve"||q==="resolve day"){setDayModal(true);answer=`Day ${s.day} resolution staged.`}setMessages(m=>[...m,{who:"AVA",text:answer}]);};
  return<main><header className="top"><button className="logo" onClick={()=>setPage("dashboard")}><span>DELENDA</span><i>.</i>QUEST</button><nav>{modules.map(m=><button className={page===m.id?"active":""} key={m.id} onClick={()=>setPage(m.id)}><span>{m.n}</span>{m.label}</button>)}</nav><div className="continuity"><span>COMMAND CONTINUITY</span><b>DAY {s.day}</b><small>DELEGATION AUTHORITY × 2</small></div><div className="day"><WarClock remaining={remaining}/><div><span>ORDERS</span><b>{DAILY_ORDERS-s.actions} / {DAILY_ORDERS}</b></div><button disabled={s.status!=="active"} onClick={()=>setDayModal(true)}>Resolve day →</button></div></header>
    <div className="strip" aria-live="polite"><span><Dot tone={tone}/>WESTERN THEATER // {balance.toUpperCase()}</span><span>LIVE FORCE {fmt(live.deployable,true)}</span><span>LOSSES {fmt(live.losses,true)}</span><span>DESERTED {fmt(live.deserted,true)}</span><span>DOCTRINE {s.doctrine}</span>{remaining>DAY_MS/2&&<span className="early">EARLY INTERCEPT // AVAILABLE</span>}<div className="strip-tools"><button className={page==="wiki"?"active":""} onClick={()=>setPage("wiki")}>WIKI</button><button onClick={()=>setReset(true)}>NEW CAMPAIGN</button></div></div>
    <div className="frame">{page==="dashboard"?<Dashboard s={s} live={live} inspect={setMetric} openSituation={()=>setSituationOpen(true)}/>:page==="campaign"?<CampaignPage s={s} selected={pendingManeuver} setSelected={setPendingManeuver} review={()=>setSituationOpen(true)}/>:page==="doctrine"?<DoctrineControlPanel s={s} select={(vector,stage)=>setPendingDoctrine({vector,stage})}/>:page==="wiki"?<WikiPage article={wikiArticle}/>:<ModulePage page={page} s={s} focus={focusFamily} select={(f,c)=>{setFamily(f);setPending(c)}}/>}</div>
    {s.status!=="active"&&<div className={`end ${s.status}`}><span>CAMPAIGN {s.status.toUpperCase()}</span><p>{s.status==="victory"?"The enemy operational system has broken beyond the prewar line.":"The state can no longer convert its remaining capacity into a viable front."}</p><button onClick={()=>setReset(true)}>Begin new campaign</button></div>}
    {ordersStamped&&<div className="completion-stamp" role="status">DAY&apos;S ORDERS ISSUED // AWAITING RESOLUTION</div>}
    <button className={`ava-button ${ava?"hide":""}`} onClick={()=>setAva(true)}><span>AM</span><div><b>AVA MOORE</b><small>{fmt(live.losses,true)} LOSSES OBSERVED // OPEN CONSOLE</small></div><i>&gt;</i></button>
    {ava&&<aside className="ava"><header><div><span>AM</span><p><b>AVA MOORE</b><small>PATTERN ANALYSIS // {moduleName(page)}</small></p></div><button onClick={()=>setAva(false)}>×</button></header><div className="ava-state"><span>DAY {s.day}</span><span>{s.actions} ACTIONS</span><span>{clockText(remaining)}</span></div><div className="messages">{messages.map((m,i)=><div className={m.who==="YOU"?"you":""} key={i}><span>{m.who}</span><p>{m.text}</p></div>)}</div><form onSubmit={run}><label>COMMAND</label><div><span>&gt;</span><input value={input} onChange={e=>setInput(e.target.value)} placeholder="situation, forecast, maneuver exploit..."/><button>RUN</button></div></form><footer>Try: situation // inspect desertion // open doctrine // maneuver exploit</footer></aside>}
    {situationOpen&&<SituationModal s={s} pending={pendingManeuver} setPending={setPendingManeuver} confirm={issueManeuver} close={()=>{setSituationOpen(false);setPendingManeuver(null)}}/>}{pendingDoctrine&&<DoctrineConfirm vector={pendingDoctrine.vector} stage={pendingDoctrine.stage} s={s} yes={internalize} no={()=>setPendingDoctrine(null)}/>} {family&&!pending&&<FamilyDrawer family={family} s={s} choose={setPending} close={()=>setFamily(null)}/>} {family&&pending&&<Confirm family={family} choice={pending} s={s} yes={issue} no={()=>setPending(null)}/>} {metric&&<MetricDrawer metric={metric} s={s} live={live} close={()=>setMetric(null)}/>} 
    {dayModal&&<Overlay close={()=>setDayModal(false)} kind="center"><div className="small-modal"><Close onClick={()=>setDayModal(false)}/><span className="eyebrow">End Day {s.day}</span><h2>Release the day to resolution?</h2><p>{s.maneuver?`${maneuverById(s.maneuver)?.label} will be resolved against ${situationForDay(s.day).sector}. `:"No maneuver order exists. Standing tempo will prosecute the day. "}{s.actions?`${s.actions} unused action${s.actions===1?"":"s"} will expire. `:""}The Butcher's Bill cannot be recalled afterward.</p><Actions cancel={()=>setDayModal(false)} action={advance} label={`Resolve Day ${s.day}`}/></div></Overlay>}
    {reset&&<Overlay close={()=>setReset(false)} kind="center"><div className="small-modal"><Close onClick={()=>setReset(false)}/><span className="eyebrow">Campaign reset</span><h2>Erase this command history?</h2><p>The army will return to its opening strength. The men already spent will become available again because this is still a playable checkpoint.</p><Actions cancel={()=>setReset(false)} action={()=>{const n=Date.now();setS(initialState());setPage("dashboard");setClock({start:n,end:n+DAY_MS});setReset(false);setMessages([{who:"AVA",text:"The opening state is restored. The reserve remains undirected."}])}} label="Reset campaign" danger/></div></Overlay>}
    {dispatch&&<Overlay close={()=>setDispatch(null)} kind="center"><div className={`dispatch ${dispatch.open?"opened":""}`}><span className="eyebrow">EYES OF THE COMMANDER ONLY // DAY {dispatch.day}</span><div className="seal">DELENDA QUEST // 27-B</div>{dispatch.open?<><Epigraph quote="Classification is power." source="AVA MOORE, Pattern Analysis Directorate"/><h2>Enemy firing schedule recovered</h2><p>Signals officers reconstructed a forty-minute gap in the interdiction cycle. Intelligence increases by one in the campaign record. The report is deterministic; the seal was only theater.</p><button onClick={()=>setDispatch(null)}>FILE DISPATCH</button></>:<><h2>Sealed Dispatch</h2><p>Contents entered into custody after resolution. Open once.</p><button onClick={()=>setDispatch({...dispatch,open:true})}>BREAK SEAL</button></>}</div></Overlay>}
  </main>;
}
